function clientHref(label: string) {
  const value = label.toLowerCase();
  if (value.includes("questionnaire")) return "/client/questionnaires/personal-magazine";
  if (value.includes("draft")) return "/client/drafts/visionary-leader";
  if (value.includes("design") || value.includes("cover")) return "/client/designs/magazine-cover-concepts";
  if (value.includes("approval") || value.includes("approve") || value.includes("review")) return "/client/approvals";
  if (value.includes("invoice") || value.includes("payment") || value.includes("pay")) return "/client/billing";
  if (value.includes("meeting") || value.includes("calendar") || value.includes("call") || value.includes("recording")) return "/client/meetings";
  if (value.includes("message")) return "/client/messages";
  if (value.includes("upload") || value.includes("file") || value.includes("asset")) return "/client/assets";
  if (value.includes("report") || value.includes("download")) return "/client/reports";
  if (value.includes("publish") || value.includes("distribution")) return "/client/publishing";
  if (value.includes("project")) return "/client/projects";
  if (value.includes("support") || value.includes("help")) return "/client/support";
  return "/client";
}

function Button({ children, primary = false, danger = false, href }: { children: React.ReactNode; primary?: boolean; danger?: boolean; href?: string }) {
  const className = `${s.button} ${primary ? s.primary : ""} ${danger ? s.danger : ""}`;
  return href ? <Link className={className} href={href}>{children}</Link> : <button className={className} type="button">{children}</button>;
}

function Pill({ children, tone = "violet" }: { children: React.ReactNode; tone?: "violet" | "green" | "orange" | "red" | "blue" | "gray" }) {
  return <span className={`${s.pill} ${s[`pill_${tone}`]}`}>{children}</span>;
}

function Panel({ title, action, children, className = "" }: { title: string; action?: string; children: React.ReactNode; className?: string }) {
  return <section className={`${s.panel} ${className}`}><header><h2>{title}</h2>{action && <Link href={clientHref(`${title} ${action}`)}>{action} <ArrowRight size={13} /></Link>}</header>{children}</section>;
}

function IconTile({ icon: Icon, tone = 0 }: { icon: IconType; tone?: number }) {
  return <span className={`${s.iconTile} ${s[`tone${tone % 6}`]}`}><Icon size={19} /></span>;
}

function MagazineCover({ className = "" }: { className?: string }) {
  return <div className={`${s.magazineCover} ${className}`}><Image alt="The Visionary Leader Magazine cover featuring Arjun Mehta" fill sizes="160px" src={coverPhoto} /><span>VISION</span><b>The<br />Visionary<br />Leader</b><small>Arjun Mehta · NextPay</small></div>;
}

function Person({ name = "Arjun Mehta", role = "Account Manager", src = portrait }: { name?: string; role?: string; src?: string }) {
  return <span className={s.person}><Image alt="" height={29} src={src} width={29} /><span><b>{name}</b><small>{role}</small></span></span>;
}

function Progress({ value }: { value: number }) {
  return <span className={s.progress}><i><b style={{ width: `${value}%` }} /></i><strong>{value}%</strong></span>;
}

function SearchBox({ placeholder }: { placeholder: string }) {
  return <label className={s.search}><Search size={16} /><input aria-label={placeholder} placeholder={placeholder} /></label>;
}

function PageHead({ title, subtitle, icon: Icon, actions }: { title: string; subtitle: string; icon?: IconType; actions?: React.ReactNode }) {
  return <div className={s.pageHead}><div>{Icon && <IconTile icon={Icon} />}<span><h1>{title}</h1><p>{subtitle}</p></span></div>{actions && <aside>{actions}</aside>}</div>;
}

const projectTabs = ["Overview", "Timeline", "Messages · 6", "Meetings", "Tasks / Requests · 3", "Questionnaire", "Drafts · 2", "Designs · 1", "Files", "Approvals · 4", "Publishing", "Distribution", "Reports", "Downloads"];

function ProjectTabs({ active = "Overview" }: { active?: string }) {
  return <nav className={s.projectTabs}>{projectTabs.map((tab) => {
    const label = tab.split(" ·")[0];
    const routes: Record<string, string> = {
      Overview: "/client/projects/visionary-leader-magazine",
      Timeline: "/client/projects/visionary-leader-magazine/timeline",
      Messages: "/client/messages",
      Meetings: "/client/meetings",
      "Tasks / Requests": "/client/tasks",
      Questionnaire: "/client/questionnaires/personal-magazine",
      Drafts: "/client/drafts/visionary-leader",
      Designs: "/client/designs/magazine-cover-concepts",
      Files: "/client/assets",
      Approvals: "/client/approvals",
      Publishing: "/client/publishing",
      Distribution: "/client/publishing",
      Reports: "/client/reports",
      Downloads: "/client/reports",
    };
    const href = routes[label] ?? "/client/projects/visionary-leader-magazine";
    return <Link className={label === active ? s.tabActive : ""} href={href} key={tab}>{tab}</Link>;
  })}</nav>;
}

